-- SettleHub 2.0 schema, as generated by Hibernate ddl-auto=update.
-- Fresh databases run this script; existing 2.0 databases are baselined at version 1
-- (spring.flyway.baseline-on-migrate) and skip it.

CREATE TABLE users (
    id          UUID                        NOT NULL,
    email       VARCHAR(255)                NOT NULL,
    password    VARCHAR(255)                NOT NULL,
    first_name  VARCHAR(255)                NOT NULL,
    last_name   VARCHAR(255),
    currency_code VARCHAR(255)              NOT NULL,
    created_at  TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    updated_at  TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_users PRIMARY KEY (id),
    CONSTRAINT uk_users_email UNIQUE (email)
);

CREATE TABLE expense_groups (
    id                  UUID                        NOT NULL,
    name                VARCHAR(255)                NOT NULL,
    group_type          VARCHAR(255),
    simplify_by_default BOOLEAN                     NOT NULL,
    currency_code       VARCHAR(255)                NOT NULL,
    invite_code         VARCHAR(16),
    archived            BOOLEAN,
    budget_cents        BIGINT,
    created_at          TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    updated_at          TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_expense_groups PRIMARY KEY (id),
    CONSTRAINT uk_expense_groups_invite_code UNIQUE (invite_code)
);

CREATE TABLE group_members (
    id        UUID                        NOT NULL,
    group_id  UUID                        NOT NULL,
    user_id   UUID                        NOT NULL,
    role      VARCHAR(255)                NOT NULL,
    joined_at TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_group_members PRIMARY KEY (id),
    CONSTRAINT uk_group_member UNIQUE (group_id, user_id),
    CONSTRAINT fk_group_members_group FOREIGN KEY (group_id) REFERENCES expense_groups (id),
    CONSTRAINT fk_group_members_user FOREIGN KEY (user_id) REFERENCES users (id)
);

CREATE TABLE expenses (
    id              UUID                        NOT NULL,
    group_id        UUID,
    description     VARCHAR(255)                NOT NULL,
    cost_cents      BIGINT                      NOT NULL,
    currency_code   VARCHAR(255)                NOT NULL,
    date            TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    creation_method VARCHAR(255)                NOT NULL,
    is_payment      BOOLEAN                     NOT NULL,
    category        VARCHAR(255),
    receipt_url     TEXT,
    created_by_id   UUID,
    created_at      TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    updated_at      TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    deleted_at      TIMESTAMP(6) WITH TIME ZONE,
    CONSTRAINT pk_expenses PRIMARY KEY (id),
    CONSTRAINT fk_expenses_group FOREIGN KEY (group_id) REFERENCES expense_groups (id),
    CONSTRAINT fk_expenses_created_by FOREIGN KEY (created_by_id) REFERENCES users (id)
);
CREATE INDEX idx_expense_group ON expenses (group_id);
CREATE INDEX idx_expense_date ON expenses (date);

CREATE TABLE expense_payers (
    id          UUID   NOT NULL,
    expense_id  UUID   NOT NULL,
    user_id     UUID   NOT NULL,
    paid_cents  BIGINT NOT NULL,
    CONSTRAINT pk_expense_payers PRIMARY KEY (id),
    CONSTRAINT fk_expense_payers_expense FOREIGN KEY (expense_id) REFERENCES expenses (id),
    CONSTRAINT fk_expense_payers_user FOREIGN KEY (user_id) REFERENCES users (id)
);
CREATE INDEX idx_expense_payer_expense ON expense_payers (expense_id);
CREATE INDEX idx_expense_payer_user ON expense_payers (user_id);

CREATE TABLE expense_splits (
    id          UUID   NOT NULL,
    expense_id  UUID   NOT NULL,
    user_id     UUID   NOT NULL,
    owed_cents  BIGINT NOT NULL,
    CONSTRAINT pk_expense_splits PRIMARY KEY (id),
    CONSTRAINT fk_expense_splits_expense FOREIGN KEY (expense_id) REFERENCES expenses (id),
    CONSTRAINT fk_expense_splits_user FOREIGN KEY (user_id) REFERENCES users (id)
);
CREATE INDEX idx_expense_split_expense ON expense_splits (expense_id);
CREATE INDEX idx_expense_split_user ON expense_splits (user_id);

CREATE TABLE settlements (
    id            UUID                        NOT NULL,
    group_id      UUID,
    payer_id      UUID                        NOT NULL,
    payee_id      UUID                        NOT NULL,
    amount_cents  BIGINT                      NOT NULL,
    currency_code VARCHAR(255)                NOT NULL,
    date          TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    created_at    TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    CONSTRAINT pk_settlements PRIMARY KEY (id),
    CONSTRAINT fk_settlements_group FOREIGN KEY (group_id) REFERENCES expense_groups (id),
    CONSTRAINT fk_settlements_payer FOREIGN KEY (payer_id) REFERENCES users (id),
    CONSTRAINT fk_settlements_payee FOREIGN KEY (payee_id) REFERENCES users (id)
);
CREATE INDEX idx_settlement_group ON settlements (group_id);
CREATE INDEX idx_settlement_payer ON settlements (payer_id);
CREATE INDEX idx_settlement_payee ON settlements (payee_id);
